create schema if not exists pv_roles;
revoke all on schema pv_roles from public;
grant usage on schema pv_roles to authenticated;
create table public.pv_role_catalog(id text primary key,body jsonb not null,revision integer not null default 1,updated_at timestamptz not null default clock_timestamp());
alter table public.pv_role_catalog enable row level security;
create policy "Public responsibility reference" on public.pv_role_catalog for select to anon,authenticated using(true);
revoke all on public.pv_role_catalog from public,anon,authenticated;grant select on public.pv_role_catalog to anon,authenticated;
create table public.pv_role_mappings(id uuid primary key default gen_random_uuid(),brief_id text not null,role_id text not null references public.pv_role_catalog(id),process_id text not null,relationship text not null default 'consulted' check(relationship in ('accountable','responsible','consulted','informed')),source_url text not null,source_location text not null,rationale text not null,deliverable text not null,state text not null default 'suggested' check(state in ('suggested','reviewed','retired')),revision integer not null default 1,reviewed_at timestamptz,unique(brief_id,role_id,process_id));
create index pv_role_mappings_role on public.pv_role_mappings(role_id);
alter table public.pv_role_mappings enable row level security;
create policy "Public role mapping rationale" on public.pv_role_mappings for select to anon,authenticated using(true);
revoke all on public.pv_role_mappings from public,anon,authenticated;grant select on public.pv_role_mappings to anon,authenticated;
create table public.pv_role_audit(id bigint generated always as identity primary key,kind text not null,key text not null,actor uuid not null references auth.users(id),at timestamptz not null default clock_timestamp(),reason text not null,before_value jsonb,after_value jsonb not null);
create index pv_role_audit_actor on public.pv_role_audit(actor);
alter table public.pv_role_audit enable row level security;
create policy "Role model editorial audit" on public.pv_role_audit for select to authenticated using((select public.is_app_admin()));
revoke all on public.pv_role_audit from public,anon,authenticated;grant select on public.pv_role_audit to authenticated;
create table public.pv_role_preferences(user_id uuid primary key references auth.users(id),role_ids text[] not null default '{}',process_ids text[] not null default '{}',revision integer not null default 1,updated_at timestamptz not null default clock_timestamp(),check(cardinality(role_ids)<=100 and cardinality(process_ids)<=100));
alter table public.pv_role_preferences enable row level security;
create policy "My responsibility preferences" on public.pv_role_preferences for select to authenticated using((select auth.jwt()->>'role')='authenticated' and user_id=(select auth.uid()));
revoke all on public.pv_role_preferences from public,anon,authenticated;grant select on public.pv_role_preferences to authenticated;

create table pv_roles.model_config(id boolean primary key default true check(id),body jsonb not null);
revoke all on pv_roles.model_config from public,anon,authenticated;
create function pv_roles.save_preference(p_roles text[],p_processes text[],p_expected integer) returns public.pv_role_preferences language plpgsql security definer set search_path='' as $$
declare r public.pv_role_preferences;cfg jsonb;
begin
 if auth.uid() is null or auth.jwt()->>'role' is distinct from 'authenticated' then raise exception 'Approved sign-in required';end if;
 select body into cfg from pv_roles.model_config;
 if p_roles is null or p_processes is null or cardinality(p_roles)>100 or cardinality(p_processes)>100 or exists(select 1 from unnest(p_roles) x where x is null or not exists(select 1 from public.pv_role_catalog c where c.id=x)) or exists(select 1 from unnest(p_processes) x where x is null or not exists(select 1 from jsonb_array_elements(cfg->'processes') p where p->>'id'=x)) then raise exception 'Choose catalog responsibilities only';end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,52));select * into r from public.pv_role_preferences where user_id=auth.uid() for update;
 if coalesce(r.revision,0) is distinct from p_expected then raise exception 'Preferences changed; reload before saving';end if;
end $$;
revoke all on function pv_roles.save_preference(text[],text[],integer) from public,anon;grant execute on function pv_roles.save_preference(text[],text[],integer) to authenticated;
create function public.save_pv_role_preferences(p_roles text[],p_processes text[],p_expected integer) returns public.pv_role_preferences language sql security invoker set search_path='' as $$select pv_roles.save_preference(p_roles,p_processes,p_expected)$$;
revoke all on function public.save_pv_role_preferences(text[],text[],integer) from public,anon;grant execute on function public.save_pv_role_preferences(text[],text[],integer) to authenticated;
create function pv_roles.edit_role(p_id text,p_expected integer,p_body jsonb,p_reason text) returns public.pv_role_catalog language plpgsql security definer set search_path='' as $$
declare r public.pv_role_catalog;old public.pv_role_catalog;cfg jsonb;x jsonb;clean jsonb;before_mapping public.pv_role_mappings;after_mapping public.pv_role_mappings;
begin
 if auth.uid() is null or not public.is_app_admin() then raise exception 'Admin access required';end if;
 if p_id is null or p_id!~'^[a-z0-9-]{3,80}$' then raise exception 'Stable role ID required';end if;
 perform public.pv_organizational_text(p_reason,'Change reason',1000);perform public.pv_organizational_text(p_body->>'label','Role label',200);perform public.pv_organizational_text(p_body->>'responsibility','Responsibility',2000);select body into cfg from pv_roles.model_config;
 if not exists(select 1 from jsonb_array_elements(cfg->'functions') f where f->>'id'=p_body->>'function_id') or jsonb_typeof(p_body->'active') is distinct from 'boolean' or jsonb_typeof(p_body->'process_ids') is distinct from 'array' or jsonb_array_length(p_body->'process_ids')>30 then raise exception 'Choose function, active status and processes';end if;
 for x in select * from jsonb_array_elements(p_body->'process_ids') loop if not exists(select 1 from jsonb_array_elements(cfg->'processes') p where p->>'id'=x#>>'{}') then raise exception 'Unknown process';end if;end loop;
 perform pg_advisory_xact_lock(hashtextextended(p_id,53));select * into old from public.pv_role_catalog where id=p_id for update;if coalesce(old.revision,0) is distinct from p_expected then raise exception 'Role changed; reload before saving';end if;
 clean:=jsonb_build_object('id',p_id,'label',trim(p_body->>'label'),'responsibility',trim(p_body->>'responsibility'),'function_id',p_body->>'function_id','process_ids',p_body->'process_ids','active',p_body->'active');
 if old.id is not null and old.body is distinct from clean then
  for before_mapping in select * from public.pv_role_mappings where role_id=p_id and state='reviewed' for update loop
   update public.pv_role_mappings set state='suggested',reviewed_at=null,revision=revision+1 where id=before_mapping.id returning * into after_mapping;
  end loop;
 end if;
end $$;
revoke all on function pv_roles.edit_role(text,integer,jsonb,text) from public,anon;grant execute on function pv_roles.edit_role(text,integer,jsonb,text) to authenticated;
create function public.admin_save_pv_role(p_id text,p_expected integer,p_body jsonb,p_reason text) returns public.pv_role_catalog language sql security invoker set search_path='' as $$select pv_roles.edit_role(p_id,p_expected,p_body,p_reason)$$;
revoke all on function public.admin_save_pv_role(text,integer,jsonb,text) from public,anon;grant execute on function public.admin_save_pv_role(text,integer,jsonb,text) to authenticated;
create function pv_roles.review_mapping(p_id uuid,p_revision integer,p_state text,p_relation text,p_reason text,p_location text,p_deliverable text) returns public.pv_role_mappings language plpgsql security definer set search_path='' as $$
declare old public.pv_role_mappings;r public.pv_role_mappings;
begin
 if auth.uid() is null or not public.is_app_admin() then raise exception 'Admin access required';end if;
 if p_state is null or p_state not in ('suggested','reviewed','retired') or p_relation is null or p_relation not in ('accountable','responsible','consulted','informed') then raise exception 'Choose state and relationship';end if;
 perform public.pv_organizational_text(p_reason,'Mapping rationale',2000);perform public.pv_organizational_text(p_location,'Source location',1000);perform public.pv_organizational_text(p_deliverable,'Suggested deliverable',2000);
 select * into old from public.pv_role_mappings where id=p_id for update;if not found or old.revision is distinct from p_revision then raise exception 'Mapping changed; reload';end if;
 update public.pv_role_mappings set state=p_state,relationship=p_relation,rationale=trim(p_reason),source_location=trim(p_location),deliverable=trim(p_deliverable),revision=revision+1,reviewed_at=case when p_state='reviewed' then clock_timestamp() else null end where id=p_id returning * into r;
end $$;
revoke all on function pv_roles.review_mapping(uuid,integer,text,text,text,text,text) from public,anon;grant execute on function pv_roles.review_mapping(uuid,integer,text,text,text,text,text) to authenticated;
create function public.admin_review_pv_role_mapping(p_id uuid,p_revision integer,p_state text,p_relation text,p_reason text,p_location text,p_deliverable text) returns public.pv_role_mappings language sql security invoker set search_path='' as $$select pv_roles.review_mapping(p_id,p_revision,p_state,p_relation,p_reason,p_location,p_deliverable)$$;
revoke all on function public.admin_review_pv_role_mapping(uuid,integer,text,text,text,text,text) from public,anon;grant execute on function public.admin_review_pv_role_mapping(uuid,integer,text,text,text,text,text) to authenticated;
create function pv_roles.add_mapping(p_brief text,p_role text,p_process text,p_source text,p_location text,p_reason text,p_deliverable text) returns public.pv_role_mappings language plpgsql security definer set search_path='' as $$
declare r public.pv_role_mappings;cfg jsonb;
begin
 if auth.uid() is null or not public.is_app_admin() then raise exception 'Admin access required';end if;
 if p_brief is null or p_brief!~'^[a-z0-9-]{3,80}$' then raise exception 'Stable brief ID required';end if;
 select body into cfg from pv_roles.model_config;if not exists(select 1 from jsonb_array_elements(cfg->'processes') x where x->>'id'=p_process) then raise exception 'Unknown process';end if;
 perform public.company_case_url(p_source);perform public.pv_organizational_text(p_location,'Source location',1000);perform public.pv_organizational_text(p_reason,'Mapping rationale',2000);perform public.pv_organizational_text(p_deliverable,'Deliverable',2000);
end $$;
revoke all on function pv_roles.add_mapping(text,text,text,text,text,text,text) from public,anon;grant execute on function pv_roles.add_mapping(text,text,text,text,text,text,text) to authenticated;
create function public.admin_add_pv_role_mapping(p_brief text,p_role text,p_process text,p_source text,p_location text,p_reason text,p_deliverable text) returns public.pv_role_mappings language sql security invoker set search_path='' as $$select pv_roles.add_mapping(p_brief,p_role,p_process,p_source,p_location,p_reason,p_deliverable)$$;
revoke all on function public.admin_add_pv_role_mapping(text,text,text,text,text,text,text) from public,anon;grant execute on function public.admin_add_pv_role_mapping(text,text,text,text,text,text,text) to authenticated;
