insert into pv_roles.model_config(body) values($model${"schema": 1, "revision": 1, "checkedOn": "2026-11-05", "status": "reference_model", "notice": "Organizational reference model, not universal legal obligations, qualification requirements or access permissions. Titles may be combined or outsourced. Statutory roles need jurisdiction-specific source review.", "functions": [{"id": "governance", "label": "Leadership & governance", "description": "Oversee the PV operating model, escalations and continuity."}, {"id": "operations", "label": "Case operations", "description": "Manage intake, processing, follow-up and delivery controls."}, {"id": "medical", "label": "Medical review & case quality", "description": "Assess medical content and case quality."}, {"id": "clinical", "label": "Clinical safety", "description": "Coordinate safety oversight for clinical development."}, {"id": "signals", "label": "Signal detection & management", "description": "Evaluate safety evidence and manage signal decisions."}, {"id": "benefit-risk", "label": "Benefit–risk & aggregate reporting", "description": "Integrate safety evidence into assessments and reports."}, {"id": "risk", "label": "Risk management", "description": "Plan, implement and assess risk controls."}, {"id": "epidemiology", "label": "Epidemiology & real-world evidence", "description": "Design and interpret population-level safety studies."}, {"id": "regulatory", "label": "Regulatory intelligence & policy", "description": "Monitor sources and assess reporting requirements."}, {"id": "submissions", "label": "Submissions & communications", "description": "Coordinate submissions and authority responses."}, {"id": "labeling", "label": "Labeling & product information", "description": "Assess and track safety information changes."}, {"id": "quality", "label": "Quality & compliance", "description": "Maintain quality oversight and improvement evidence."}, {"id": "local", "label": "PSMF & local PV", "description": "Maintain system descriptions and local interfaces."}, {"id": "partners", "label": "Partners & outsourcing", "description": "Allocate and oversee shared PV activities."}, {"id": "systems", "label": "Safety systems & configuration", "description": "Maintain controlled safety technology and integrations."}, {"id": "data", "label": "Data & technology assurance", "description": "Maintain data integrity and controlled technology changes."}, {"id": "training", "label": "Training & knowledge", "description": "Maintain controlled procedures and competency support."}, {"id": "interfaces", "label": "Cross-functional interfaces", "description": "Coordinate safety-related handoffs across disciplines."}], "processes": [{"id": "governance", "label": "Safety governance", "keywords": []}, {"id": "psmf", "label": "PSMF management", "keywords": []}, {"id": "intake", "label": "Safety intake & collection", "keywords": ["case intake", "adverse event report"]}, {"id": "case-processing", "label": "Case processing & follow-up", "keywords": ["icsr", "case processing"]}, {"id": "reconciliation", "label": "Reconciliation", "keywords": []}, {"id": "medical-review", "label": "Medical review", "keywords": []}, {"id": "case-quality", "label": "ICSR quality control", "keywords": []}, {"id": "clinical-safety", "label": "Clinical safety monitoring", "keywords": ["clinical trial", "pre-ind", "first-in-human", "investigational"]}, {"id": "aggregate-reporting", "label": "Aggregate reporting", "keywords": ["psur", "pbrer", "dsur", "eurd"]}, {"id": "signal-detection", "label": "Signal detection", "keywords": []}, {"id": "signal-management", "label": "Signal management", "keywords": ["signal", "prac"]}, {"id": "benefit-risk", "label": "Benefit–risk review", "keywords": []}, {"id": "risk-management", "label": "Risk management & minimisation", "keywords": ["risk management", "rmp", "risk minimisation", "rems"]}, {"id": "epidemiology", "label": "Epidemiology / safety studies", "keywords": ["pass", "observational study", "epidemiology"]}, {"id": "reg-intelligence", "label": "Regulatory intelligence", "keywords": []}, {"id": "reg-reporting", "label": "Reporting policy", "keywords": ["reporting deadline", "safety reporting", "expedited report"]}, {"id": "submissions", "label": "Submission operations", "keywords": ["submission", "rolling ind", "pre-ind"]}, {"id": "communications", "label": "Safety communications", "keywords": []}, {"id": "labeling", "label": "Safety labeling", "keywords": ["labeling", "labelling", "smPC", "prescribing information"]}, {"id": "quality", "label": "Quality system & CAPA", "keywords": ["inspection", "audit", "capa"]}, {"id": "inspection", "label": "Audit & inspection readiness", "keywords": []}, {"id": "local-pv", "label": "Local PV interfaces", "keywords": []}, {"id": "vendor-oversight", "label": "Partner & vendor oversight", "keywords": []}, {"id": "system-configuration", "label": "Safety system configuration", "keywords": ["configuration", "reporting rule", "database"]}, {"id": "transmission", "label": "E2B / transmission", "keywords": ["e2b", "masking", "eudravigilance", "transmission", "gateway"]}, {"id": "data-integrity", "label": "Data integrity & records", "keywords": ["privacy", "personal data", "data integrity"]}, {"id": "validation", "label": "Validation & change control", "keywords": []}, {"id": "terminology", "label": "Terminology governance", "keywords": ["meddra", "whodrug", "rxnorm"]}, {"id": "training", "label": "Training & competency", "keywords": ["training", "competency"]}, {"id": "cross-functional", "label": "Cross-functional handoffs", "keywords": []}], "references": [{"title": "EMA GVP framework", "url": "https://www.ema.europa.eu/en/human-regulatory-overview/post-authorisation/pharmacovigilance-post-authorisation/good-pharmacovigilance-practices-gvp"}, {"title": "EMA GVP Module I — qualifications and QPPV role", "url": "https://www.ema.europa.eu/en/documents/scientific-guideline/guideline-good-pharmacovigilance-practices-module-i-pharmacovi